import { path, Plugin, CallExpressionShape } from '@servicenow/sdk-build-core'
import { createProject } from '../test-utils'

const LIB = {
    path: 'lib.d.ts',
    content: `
declare module '@servicenow/sdk/core' {
    export function TestEntity(...args: any[]): any
    export function TestRef(...args: any[]): any
}
`,
}

const EntityPlugin = Plugin.create({
    name: 'EntityPlugin',
    shapes: [
        {
            shape: CallExpressionShape,
            async toRecord(shape, { factory }) {
                if (shape.getCallee() !== 'TestEntity') {
                    return { success: false }
                }
                const arg = shape.getArgument(0).asObject()
                return {
                    success: true,
                    value: await factory.createRecord({
                        source: shape,
                        table: 'test_entity',
                        explicitId: arg.get('$id'),
                        properties: arg.transform(({ $ }) => ({
                            name: $,
                        })),
                    }),
                }
            },
        },
    ],
})

const RefPlugin = Plugin.create({
    name: 'RefPlugin',
    shapes: [
        {
            shape: CallExpressionShape,
            async toRecord(shape, { factory }) {
                if (shape.getCallee() !== 'TestRef') {
                    return { success: false }
                }
                const arg = shape.getArgument(0).asObject()
                return {
                    success: true,
                    value: await factory.createRecord({
                        source: shape,
                        table: 'test_ref',
                        explicitId: arg.get('$id'),
                        properties: arg.transform(({ $ }) => ({
                            entity: $,
                        })),
                    }),
                }
            },
        },
    ],
})

describe('Now.ref with Now.ID cross-plugin ordering', () => {
    test('Entity plugin registered before ref plugin', async () => {
        const project = createProject({ rootDir: path.resolve(__dirname, 'project') })
        project.addFile(LIB)
        project.getPlugins().prepend(EntityPlugin, RefPlugin)

        const entityId = project.registerExplicitId('test_entity', 'my-entity')
        const refId = project.registerExplicitId('test_ref', 'my-ref')

        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { TestEntity, TestRef } from '@servicenow/sdk/core'

TestEntity({ $id: Now.ID['my-entity'], name: 'hello' })
TestRef({ $id: Now.ID['my-ref'], entity: Now.ref('test_entity', 'my-entity') })
`,
        })

        const output = await file.getOutput()
        expect(output).toHaveLength(2)

        const entityXml = output.find((x) => x.path.includes(entityId))
        const refXml = output.find((x) => x.path.includes(refId))

        expect(entityXml).toBeDefined()
        expect(refXml).toBeDefined()
        expect(refXml.content).toContain(entityId)
    })

    test('Ref plugin registered before entity plugin', async () => {
        const project = createProject({ rootDir: path.resolve(__dirname, 'project') })
        project.addFile(LIB)
        project.getPlugins().prepend(RefPlugin, EntityPlugin)

        const entityId = project.registerExplicitId('test_entity', 'my-entity')
        const refId = project.registerExplicitId('test_ref', 'my-ref')

        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { TestEntity, TestRef } from '@servicenow/sdk/core'

TestRef({ $id: Now.ID['my-ref'], entity: Now.ref('test_entity', 'my-entity') })
TestEntity({ $id: Now.ID['my-entity'], name: 'hello' })
`,
        })

        const output = await file.getOutput()
        expect(output).toHaveLength(2)

        const entityXml = output.find((x) => x.path.includes(entityId))
        const refXml = output.find((x) => x.path.includes(refId))

        expect(entityXml).toBeDefined()
        expect(refXml).toBeDefined()
        expect(refXml.content).toContain(entityId)
    })

    test('Unregistered Now.ID key falls back to raw string', async () => {
        const project = createProject({ rootDir: path.resolve(__dirname, 'project') })
        project.addFile(LIB)
        project.getPlugins().prepend(RefPlugin)

        const refId = project.registerExplicitId('test_ref', 'my-ref')

        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { TestRef } from '@servicenow/sdk/core'

TestRef({ $id: Now.ID['my-ref'], entity: Now.ref('test_entity', 'nonexistent-key') })
`,
        })

        const output = await file.getOutput()
        expect(output).toHaveLength(1)

        const refXml = output.find((x) => x.path.includes(refId))
        expect(refXml).toBeDefined()
        expect(refXml.content).toContain('nonexistent-key')
    })
})
